/// 引擎每轮维护调一次:对账 + 判定 + 抬指重建 + 把原因写回(见 task-8 C)。
///
/// 返回本次自愈的原因(调用方据此写 INFO 日志);None = 这一轮没动作。
fn self_heal_tick(
    ctl: &ControlClient,
    enabled: bool,
    cfg: &Aim,
    st: &mut AimState,
    live: &mut AimLive,
    local_pointers: usize,
    now: Instant,
) -> Option<&'static str> {
