        ledger_mismatch(
            live.device_pointers,
            local_pointers,
            st.down,
            live.physical_touch,
            st.ledger_reflects_injection,
        )
    } else {
        None
    };
    let reason = self_heal_decision(enabled, cfg.self_heal, live.ui_busy, req, mismatch)?;
    if !self_heal_lift(ctl, st, now) {
        return None;
    }
    st.self_heal_reason = reason;
