    #[test]
    fn self_heal_throttles_to_one_lift_per_300ms() {
        use crate::control::{ACTION_UP, ControlCmd};

        let ctl = ControlClient::for_test(1000, 1000);
        let mut st = AimState {
            down: true,
            cur: (500, 500),
            ..AimState::default()
        };
        let t0 = Instant::now();
        assert!(self_heal_lift(&ctl, &mut st, t0), "第一次必须抬指");
