    /// 谈起,白白多一条一直在读的 `getevent` 流。
    /// 为什么只起一个:监听线程是 detach 的(`adb::watch_physical_touch` 只返回
    /// `Receiver`,没有停止句柄),重复起就是泄漏线程 ⇒ 按序列号**粘住**,
    /// 只有断连/换设备(清掉 [`Self::touch_watch_serial`])之后才允许重建一次。
    fn maybe_physical_touch_watch(&mut self) {
        if self.touch_start_rx.is_some() || self.touch_rx.is_some() {
            return;
        }
        let online = {
            let g = lock_shared(&self.shared);
            g.enabled && g.control.as_ref().is_some_and(|c| c.is_connected())
        };
        if !online || self.server.is_none() {
            return;
        }
        let serial = self.serial();
        if serial.is_empty() || self.touch_watch_serial.as_deref() == Some(serial.as_str()) {
            return;
        }
        self.touch_watch_serial = Some(serial.clone());
        let (tx, rx) = channel();
        self.touch_start_rx = Some(rx);
        // 起监听本身要先走 adb(找触摸屏节点),必须在**工作线程**上做;
        // 拿到 Receiver 再交回界面(每帧 `poll_physical_touch` 收边沿)。
        std::thread::spawn(move || {
            let path = adb::touch_screen_path(&serial);
            let watch = adb::watch_physical_touch(serial);
            let _ = tx.send((path.unwrap_or_else(|| "未知".to_string()), watch));
        });
    }

    /// 每帧收一次触摸边沿:**状态翻转时**写一条 INFO,并灌进 `Shared`。
    ///
    /// **`Up` 边沿(手离开手机)⇒ 立刻在 `Shared` 里留一个自愈请求**,由引擎在
    /// 下一轮维护里取走并抬指重建(见 `engine::self_heal_tick`)—— 这就是把用户
    /// 现在手动按的那一下自动化。
    fn poll_physical_touch(&mut self) {
        // ① 先收监听器的交接(工作线程 → 界面)。
        if let Some(rx) = self.touch_start_rx.as_ref() {
            match rx.try_recv() {
                Ok((path, watch)) => {
                    self.touch_start_rx = None;
                    self.touch_rx = Some(watch);
                    self.log(format!(
                        "手机触摸监听已启动(只读 getevent {path}):手离开手机时会自动抬指重建\
                         (卡死自愈)"
                    ));
                }
                Err(std::sync::mpsc::TryRecvError::Empty) => {}
                Err(std::sync::mpsc::TryRecvError::Disconnected) => self.touch_start_rx = None,
            }
        }
        // ② 再收边沿。一帧最多处理 64 条:这是一条"一直在跑"的流,不能让它把某一帧
        //    的界面饿死(剩下的下一帧继续收)。
        let mut events: Vec<adb::PhysicalTouch> = Vec::new();
        if let Some(rx) = self.touch_rx.as_ref() {
            for _ in 0..64 {
                match rx.try_recv() {
                    Ok(e) => events.push(e),
                    Err(std::sync::mpsc::TryRecvError::Empty) => break,
                    Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                        self.touch_rx = None;
                        break;
                    }
                }
            }
        }
        if events.is_empty() {
            return;
        }
        let mut lines: Vec<&'static str> = Vec::new();
        let mut heal_req = false;
        {
            let mut g = lock_shared(&self.shared);
            for e in events {
                let touched = match e {
                    adb::PhysicalTouch::Down => true,
                    adb::PhysicalTouch::Up => false,
                };
                // 只在**真的翻转**时写日志与状态:同一个方向的重复上报(手指多点/
                // 重复 tracking id)不该刷屏,也不该被当成新的 Up 边沿去反复请求自愈。
                if g.aim_live.physical_touch == touched {
                    continue;
                }
                g.aim_live.physical_touch = touched;
                if touched {
                    lines.push("手机被手触摸");
                } else {
                    lines.push("手离开手机");
                    // Up 边沿 = 用户报的那个触发动作刚刚结束 ⇒ 请求一次自愈。
                    heal_req = true;
                }
            }
            if heal_req {
                g.aim_live.self_heal_req = Some(engine::SELF_HEAL_REASON_TOUCH_UP);
            }
        }
        for l in lines {
            self.log(l);
        }
    }"}

