            } else {
                None
            }
        }
        other => {
            st.ledger_zero_streak = 0;
            st.ledger_zero_sample_at = None;
            other
        }
    };
    let reason = self_heal_decision(enabled, cfg.self_heal, live.ui_busy, req, mismatch.map(LedgerMismatch::label))?;
