#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum LedgerMismatch {
    /// 账本触点为 0,而本地认为瞄准指还按着
    ZeroWhileDown,
    /// 账本触点比本地多(我们发出的抬起没到设备端 / 手势被丢)
    MoreThanLocal,
}

impl LedgerMismatch {
    /// 日志与悬浮窗用的那一句话
    fn label(self) -> &'static str {
        match self {
            Self::ZeroWhileDown => "设备端账本触点为 0,而本地认为瞄准指还按着",
            Self::MoreThanLocal => "设备端账本触点比本地多(我们发出的抬起没到设备端)",
        }
    }
}

/// 账本对账(**纯函数**,单测钉着):设备端账本与本地记账对不上时给出原因。
///
/// 判据(task-8 原文):

diffs.oldText:
    aim_down: bool,
    physical_touch: bool,
    trusted: bool,
) -> Option<&'static str> {
    let n = ledger? as usize;
    if aim_down && n == 0 && trusted {
        return Some("设备端账本触点为 0,而本地认为瞄准指还按着");
    }
    if !physical_touch && n > local {
        return Some("设备端账本触点比本地多(我们发出的抬起没到设备端)");
    }
    None
}

diffs.newText:
    aim_down: bool,
    physical_touch: bool,
    trusted: bool,
) -> Option<LedgerMismatch> {
    let n = ledger? as usize;
    if aim_down && n == 0 && trusted {
        return Some(LedgerMismatch::ZeroWhileDown);
    }
    if !physical_touch && n > local {
        return Some(LedgerMismatch::MoreThanLocal);
    }
    None
}

